        check:{q:'Which is the strongest pilot use case?',options:['Answer every employee question','Replace the documentation site','Resolve version-specific setup questions using approved guides','Deploy the newest model company-wide'],answer:2,explanation:'It names a bounded task, implies known sources and versions, and can be evaluated with representative questions.'}
