        lab:{title:'Design a 12-case evaluation set',task:'Create four normal cases, three edge cases, two high-risk cases, two adversarial cases, and one abstention case. Define evidence and expected behavior for each.',deliverable:'A versioned test-set specification with tags, criteria, and pass rules.'},
