  $('#curriculum-nav').innerHTML=modules.map(m=>`<section class="nav-group"><button class="nav-group-toggle" type="button"><span class="group-number">${m.number}</span><span>${m.title}</span><span class="chevron">⌄</span></button><div class="nav-lessons">${m.lessons.map(l=>`<a class="nav-lesson" data-lesson="${l.id}" href="#/lesson/${l.id}"><span class="completion-dot">✓</span><span>${esc(l.title)}</span></a>`).join('')}</div></section>`).join('');
  $$('.nav-group-toggle').forEach(btn=>btn.addEventListener('click',()=>btn.closest('.nav-group').classList.toggle('closed')));
