function pageHero({eyebrow,title,dek,meta=[],crumb=''}){return `<header class="page-hero">${crumb?`<div class="breadcrumbs"><a href="#/home">Learning Lab</a><span>/</span><span>${esc(crumb)}</span></div>`:''}<div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p class="dek">${esc(dek)}</p>${meta.length?`<div class="meta-row">${meta.map(x=>`<span class="meta-chip">${esc(x)}</span>`).join('')}</div>`:''}</header>`;}

