function renderCaseStudy(){
  setActive('');setToc([{id:'challenge',label:'Challenge'},{id:'diagnosis',label:'Diagnosis'},{id:'intervention',label:'Intervention'},{id:'evidence',label:'Evidence plan'},{id:'takeaways',label:'Takeaways'}]);document.title='Illustrative Case Study | Baseframe Learning Lab';
  $('#content').innerHTML=`${pageHero({eyebrow:'Free illustrative case study',title:'From fragmented product content to a governed AI-support pilot',dek:'A realistic example of how The Baseframe method connects content operations, knowledge architecture, retrieval, evaluation, and decision ownership. This is a teaching case—not a claim about a named client.',meta:['Enterprise software','12-week pilot design','Composite scenario'],crumb:'Case study'})}<article class="lesson-body case-study"><section class="lesson-section" id="challenge"><h2>The challenge</h2><p>A global software company wants an AI assistant to help support agents answer installation questions. Its documentation spans a public portal, internal runbooks, release notes, tickets, and regional PDFs. Multiple versions remain searchable, ownership changed during a reorganization, and the same procedure contains conflicting prerequisites.</p><div class="case-metrics"><div><strong>5</strong><span>source systems</span></div><div><strong>3</strong><span>product versions</span></div><div><strong>12</strong><span>languages in scope later</span></div></div><div class="callout warning"><strong>The visible symptom</strong><p>The prototype produces fluent answers but sometimes cites obsolete instructions. The team initially proposes prompt tuning; the evidence points to source authority and retrieval eligibility.</p></div></section><section class="lesson-section" id="diagnosis"><h2>The diagnosis</h2><div class="concept-grid"><article class="concept-card"><span>01</span><h3>Authority</h3><p>No enforceable rule identifies which source wins when public documentation and internal runbooks disagree.</p></article><article class="concept-card"><span>02</span><h3>Lifecycle</h3><p>Superseded pages remain indexed because status, effective date, and replacement relationships are inconsistent.</p></article><article class="concept-card"><span>03</span><h3>Structure</h3><p>Steps are separated from prerequisites during chunking, so retrieved evidence can be technically incomplete.</p></article><article class="concept-card"><span>04</span><h3>Evaluation</h3><p>The demo set contains happy-path questions but no wrong-version, missing-context, or escalation tests.</p></article></div></section><section class="lesson-section" id="intervention"><h2>The intervention</h2><ol class="workflow"><li><span><b>Bound the pilot.</b> Limit answers to installation for Product A versions 4–5, using approved English sources with citation and escalation.</span></li><li><span><b>Define source authority.</b> Register canonical sources, owners, status, effective dates, risk tier, and AI eligibility.</span></li><li><span><b>Preserve context.</b> Use structure-aware chunks and parent context so prerequisites travel with procedures.</span></li><li><span><b>Build the evaluation set.</b> Test representative, adversarial, wrong-version, and unsupported questions before release.</span></li><li><span><b>Create decision rights.</b> Assign owners for source approval, retrieval policy, quality thresholds, incidents, and expansion.</span></li></ol></section><section class="lesson-section" id="evidence"><h2>The evidence plan</h2><div class="evidence-table"><div><strong>Quality</strong><span>Grounded claim accuracy, citation support, version correctness, and task completion</span></div><div><strong>Safety</strong><span>Abstention on unsupported questions and escalation for account-specific guidance</span></div><div><strong>Operations</strong><span>Time to repair a failed answer, owner response, and stale-source removal</span></div><div><strong>Business</strong><span>Agent handling time, repeat contacts, escalation rate, and user confidence</span></div></div><p class="case-note">Targets should be set after a measured baseline. This case intentionally avoids invented outcome percentages.</p></section><section class="lesson-section" id="takeaways"><h2>What this case demonstrates</h2><ul class="objectives"><li>AI quality is an operating-system problem, not only a model problem.</li><li>Source authority and lifecycle controls often create more leverage than prompt changes.</li><li>A bounded pilot makes failures diagnosable and expansion decisions evidence-based.</li><li>Evaluation must connect technical quality to user and business outcomes.</li></ul><div class="conversion-banner"><div><div class="eyebrow">Apply this method</div><h2>Turn the case into your working plan.</h2><p>Use the $79 pilot Practitioner Toolkit, join the live pilot workshop, or discuss a tailored team engagement.</p></div><a class="button primary" href="#/offers">See implementation options →</a></div></section></article>`;
}

function renderOffers(){ $('#content').innerHTML=pageHero({eyebrow:'Explore · Build · Advisory',title:'Choose your learning offer',dek:'Free samples, implementation toolkits, and scoped advisory. Each offering has its own navigation and detailed access options.',crumb:'Offers'})+`<div class="concept-grid"><article class="concept-card"><h2>AI Content Strategy</h2><p>Choose where AI belongs in your content workflow, define the evidence it needs, and assign review decisions.</p><a class="button" href="https://sharmiladas.github.io/thebaseframe/ai-content-strategy.html">Explore offering →</a></article><article class="concept-card"><h2>Knowledge Management</h2><p>Make knowledge easier to find, reuse, improve, and maintain while preserving clear ownership.</p><a class="button" href="https://sharmiladas.github.io/thebaseframe/knowledge-management.html">Explore offering →</a></article><article class="concept-card"><h2>Knowledge Graphs</h2><p>Build a small evidence-backed model of entities and relationships, then test whether it answers useful questions.</p><a class="button" href="https://sharmiladas.github.io/thebaseframe/knowledge-graphs.html">Explore offering →</a></article><article class="concept-card"><h2>TPM Agent Kit</h2><p>Turn a complex initiative into an executable program with visible dependencies, decisions, risks, and launch evidence.</p><a class="button" href="https://sharmiladas.github.io/thebaseframe/tpm.html">Explore offering →</a></article><article class="concept-card"><h2>AI Content Quality Lab</h2><p>Evaluate answers against approved sources and use the evidence to decide what to fix or release.</p><a class="button" href="https://sharmiladas.github.io/thebaseframe/content-quality-lab.html">Explore offering →</a></article></div><p><a class="button" href="https://sharmiladas.github.io/thebaseframe/learning.html">View all offers, workshops, and consulting →</a></p>`; document.getElementById('on-this-page').innerHTML=''; }
function renderLesson(id){
  const l=allLessons.find(x=>x.id===id);if(!l){location.hash='#/home';return;}
  state.last=id;localStorage.setItem('baseframe-last',id);setActive(id);document.title=`${l.title} | Baseframe Learning Lab`;
  const toc=[['objectives','Objectives'],['concepts','Core concepts'],['method','Method'],['example','Worked example'],['lab','Practice lab'],['checklist','Quality checklist'],['knowledge-check','Knowledge check']].map(([id,label])=>({id,label}));setToc(toc);
  const idx=allLessons.findIndex(x=>x.id===id),prev=allLessons[idx-1],next=allLessons[idx+1],complete=state.completed.has(id);
  $('#content').innerHTML=`${pageHero({eyebrow:`${l.module.number} · ${l.module.title}`,title:l.title,dek:l.summary,meta:[l.time,l.level,`Lesson ${idx+1} of ${allLessons.length}`],crumb:l.module.title})}<article class="lesson-body"><section class="lesson-section" id="objectives"><h2>Learning objectives</h2><ul class="objectives">${l.objectives.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><section class="lesson-section" id="concepts"><h2>Core concepts</h2><div class="concept-grid">${l.concepts.map((c,i)=>`<article class="concept-card"><span>0${i+1}</span><h3>${esc(c[0])}</h3><p>${esc(c[1])}</p></article>`).join('')}</div></section><section class="lesson-section" id="method"><h2>How to apply it</h2>${l.body.map(p=>`<p>${esc(p)}</p>`).join('')}${l.id==='knowledge-graphs'?'<div class="callout success"><strong>Start with the complete knowledge graph course</strong><p>Learn what each concept means, why a graph matters, and how to build, query, and maintain an evidence-backed graph.</p><a href="knowledge-graph-course.html">Open the six-chapter course →</a></div>':''}<ol class="workflow">${l.workflow.map(x=>`<li><span>${esc(x)}</span></li>`).join('')}</ol></section><section class="lesson-section" id="example"><h2>Worked example</h2><div class="example-box"><div class="box-title">${esc(l.example.title)}<span>EXAMPLE</span></div><div class="box-content"><p>${esc(l.example.content)}</p></div></div></section><section class="lesson-section" id="lab"><h2>Practice lab</h2><div class="lab-box"><div class="box-title">${esc(l.lab.title)}<span>APPLY</span></div><div class="box-content"><h3>Your task</h3><p>${esc(l.lab.task)}</p><div class="callout success"><strong>Deliverable</strong><p>${esc(l.lab.deliverable)}</p></div></div></div></section><section class="lesson-section" id="checklist"><h2>Quality checklist</h2><ul class="checklist">${l.checklist.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><section class="lesson-check" id="knowledge-check"><h2>Knowledge check</h2><p>${esc(l.check.q)}</p><form class="check-form" data-answer="${l.check.answer}"><div class="check-options">${l.check.options.map((x,i)=>`<label class="check-option"><input type="radio" name="check" value="${i}"><span>${esc(x)}</span></label>`).join('')}</div><button class="button primary check-submit" type="submit">Check answer</button><div class="check-feedback" aria-live="polite"></div></form></section><nav class="lesson-actions">${prev?`<a class="button" href="#/lesson/${prev.id}">← ${esc(prev.title)}</a>`:'<span></span>'}<button class="button ${complete?'complete':'primary'} mark-complete" type="button" data-id="${id}">${complete?'✓ Completed':'Mark lesson complete'}</button>${next?`<a class="button" href="#/lesson/${next.id}">${esc(next.title)} →</a>`:`<a class="button primary" href="#/assessment">Final assessment →</a>`}</nav></article>`;
  $('.check-form').addEventListener('submit',e=>{e.preventDefault();const chosen=e.currentTarget.querySelector('input:checked'),out=$('.check-feedback',e.currentTarget);if(!chosen){out.textContent='Choose an answer first.';out.style.color='#8a5711';return;}const good=Number(chosen.value)===l.check.answer;out.textContent=(good?'Correct. ':'Not quite. ')+l.check.explanation;out.style.color=good?'#17673f':'#9a3d35';});
  $('.mark-complete').addEventListener('click',e=>{state.completed.add(id);saveProgress();e.currentTarget.className='button complete mark-complete';e.currentTarget.textContent='✓ Completed';showToast('Lesson marked complete');});
}

function renderGlossary(){
  setActive('');setToc([]);document.title='Glossary | Baseframe Learning Lab';
  $('#content').innerHTML=`${pageHero({eyebrow:'Reference',title:'Knowledge systems glossary',dek:'Plain-language definitions for the architecture, retrieval, evaluation, and governance concepts used throughout the Learning Lab.',meta:[`${glossary.length} terms`],crumb:'Glossary'})}<div class="glossary-tools"><input id="glossary-filter" type="search" placeholder="Filter glossary terms…" aria-label="Filter glossary terms"></div><section class="glossary-list" id="glossary-list">${glossary.map(g=>`<article class="glossary-item" data-text="${esc((g[0]+' '+g[1]).toLowerCase())}"><h3>${esc(g[0])}</h3><p>${esc(g[1])}</p></article>`).join('')}</section>`;
  $('#glossary-filter').addEventListener('input',e=>{const q=e.target.value.trim().toLowerCase();$$('.glossary-item').forEach(item=>item.hidden=q&&!item.dataset.text.includes(q));});
}

function renderAssessment(){
  setActive('');setToc([]);document.title='Final Assessment | Baseframe Learning Lab';
  const questions=allLessons.map((l,i)=>({...l.check,domain:l.module.title,n:i+1}));
  $('#content').innerHTML=`${pageHero({eyebrow:'Final assessment',title:'Test your knowledge-system judgment',dek:'Apply concepts across architecture, retrieval, evaluation, governance, and program delivery. Your result includes a domain-by-domain readiness profile.',meta:[`${questions.length} questions`,'80% recommended pass','Answers saved only for this attempt'],crumb:'Assessment'})}<section class="assessment-intro"><div class="assessment-stats"><div class="assessment-stat"><strong>${questions.length}</strong><span>scenario questions</span></div><div class="assessment-stat"><strong>6</strong><span>knowledge domains</span></div><div class="assessment-stat"><strong>80%</strong><span>recommended pass</span></div></div></section><form id="assessment-form">${questions.map(q=>`<article class="quiz-question"><small>${esc(q.domain)} · ${q.n}/${questions.length}</small><h3>${esc(q.q)}</h3><div class="quiz-options">${q.options.map((o,i)=>`<label class="quiz-option"><input type="radio" name="q${q.n}" value="${i}"><span>${esc(o)}</span></label>`).join('')}</div></article>`).join('')}<div class="assessment-submit"><span id="answered-count">0 of ${questions.length} answered</span><button class="button primary" type="submit">Score my assessment</button></div></form><div id="assessment-result"></div>`;
  const form=$('#assessment-form');form.addEventListener('change',()=>{$('#answered-count').textContent=`${new FormData(form).keys?new Set([...new FormData(form).keys()]).size:0} of ${questions.length} answered`;});
  form.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(form),answered=new Set([...data.keys()]).size;if(answered<questions.length){showToast(`Answer all ${questions.length} questions before scoring`);return;}let correct=0;const domains={};questions.forEach(q=>{domains[q.domain]??={right:0,total:0};domains[q.domain].total++;if(Number(data.get('q'+q.n))===q.answer){correct++;domains[q.domain].right++;}});const pct=Math.round(correct/questions.length*100),pass=pct>=80;$('#assessment-result').innerHTML=`<section class="assessment-result"><div class="result-head"><div class="result-score">${pct}%</div><h2>${pass?'Strong systems foundation':'Keep building your systems judgment'}</h2><p>You answered ${correct} of ${questions.length} questions correctly. ${pass?'You demonstrated connected thinking across the course domains.':'Review the lowest-scoring domains, repeat their labs, and try again.'}</p></div><div class="result-body"><h3>Domain profile</h3><div class="domain-bars">${Object.entries(domains).map(([name,v])=>{const p=Math.round(v.right/v.total*100);return `<div class="domain-bar"><div><span>${esc(name)}</span><strong>${p}%</strong></div><div class="domain-bar-track"><span style="width:${p}%"></span></div></div>`}).join('')}</div><div class="callout ${pass?'success':'warning'}"><strong>${pass?'Recommended next step':'Focus area'}</strong><p>${pass?'Apply the 90-day pilot and evaluation labs to one real use case, then use the evidence to shape an advisory or implementation plan.':'Start with the lowest domain above. Revisit its three lessons and complete each practice deliverable before retaking the assessment.'}</p></div><button class="button" type="button" id="retake">Retake assessment</button></div></section>`;$('#assessment-result').scrollIntoView({behavior:'smooth'});$('#retake').addEventListener('click',()=>{form.reset();$('#answered-count').textContent=`0 of ${questions.length} answered`;$('#assessment-result').innerHTML='';scrollTo({top:0,behavior:'smooth'});});});
}

function route(){
  const hash=location.hash||'#/home',parts=hash.replace(/^#\//,'').split('/');
  if(parts[0]==='lesson')renderLesson(parts[1]);else if(parts[0]==='case-study')renderCaseStudy();else if(parts[0]==='offers')renderOffers();else if(parts[0]==='glossary')renderGlossary();else if(parts[0]==='assessment')renderAssessment();else renderHome();
  $('#sidebar').classList.remove('open');$('#mobile-menu').setAttribute('aria-expanded','false');scrollTo(0,0);$('#content').focus({preventScroll:true});
}

function showToast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>t.classList.remove('show'),2200);}

function openSearch(){const d=$('#search-dialog');d.hidden=false;document.body.style.overflow='hidden';$('#search-input').value='';renderSearch('');setTimeout(()=>$('#search-input').focus(),20);}
function closeSearch(){const d=$('#search-dialog');d.hidden=true;document.body.style.overflow='';$('#search-trigger').focus();}
function renderSearch(query){
  const q=query.trim().toLowerCase();let matches=allLessons.filter(l=>!q||[l.title,l.summary,l.module.title,...l.objectives,...l.concepts.flat()].join(' ').toLowerCase().includes(q));
  $('#search-results').innerHTML=matches.length?matches.slice(0,12).map(l=>`<a class="search-result" href="#/lesson/${l.id}"><small>${l.module.number} · ${esc(l.module.title)}</small><strong>${esc(l.title)}</strong><span>${esc(l.summary)}</span></a>`).join(''):`<div class="empty-search">No lessons match “${esc(query)}”. Try a term such as retrieval, metadata, evaluation, or governance.</div>`;
  $$('.search-result',$('#search-results')).forEach(a=>a.addEventListener('click',closeSearch));
}

renderNav();route();
window.addEventListener('hashchange',route);
$('#mobile-menu').addEventListener('click',e=>{const open=$('#sidebar').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open));});
$('#search-trigger').addEventListener('click',openSearch);$('#search-close').addEventListener('click',closeSearch);$('#search-input').addEventListener('input',e=>renderSearch(e.target.value));
$('#search-dialog').addEventListener('click',e=>{if(e.target===e.currentTarget)closeSearch();});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch();}if(e.key==='Escape'&&!$('#search-dialog').hidden)closeSearch();});
$('#reset-progress').addEventListener('click',()=>{if(confirm('Reset all completed lessons and start again?')){state.completed.clear();saveProgress();showToast('Progress reset');route();}});
